ewcommand{\ibksp}{\hspace{-1.5em}} % graphics for parallelogram symbol 
ewcommand\pgram{ \setlength{\unitlength}{1pt}  egin{picture}(11,8)(0,0) \linethickness{0.5pt} \put(1,0){\line(1,0){9}} \put(1,0){\line(0,1){5}} \put(1,5){\line(1,0){9}} \put(10,0){\line(0,1){5}} \end{picture}}

% simulated chapter heading & toc command 
ewcommand\mybook[2]{ 
ewpage egin{center}{\LARGE #1.}  igskip\{\large \uppercase{#2}}\  igskip ule[1ex]{3cm}{.2pt}\  igskip {\large DEFINITIONS.}\end{center} 
oindent \addtocontents{toc}{ igskip\protect\centering {\large #1.}\medskip} \addcontentsline{toc}{section}{\protect \ibksp	extsf{#2,}} \addcontentsline{toc}{section}{Definitions,} } % Proposition header - all centered 
ewcommand\myprop[2]{  igskip\Needspace*{4 aselineskip} egin{center}	extsc{#1}\\medskip\emph{#2}\par\end{center} } % Proposition header - first line only centered 
ewcommand\mypropl[2]{  igskip\Needspace*{4 aselineskip} egin{center}	extsc{#1}\end{center} \hspace{\parindent}\emph{#2}\par\medskip
